// View 6: Mission Stress Simulator
function initSimulator() {
  const runBtn = document.getElementById("runSimulatorBtn");
  const failureToggle = document.getElementById("simFailureToggle");
  const failureOptions = document.getElementById("simFailureOptions");
  const durationSlider = document.getElementById("simDurationSlider");
  const durationVal = document.getElementById("simDurationVal");
  const ganjaToggle = document.getElementById("simGanjaToggle");

  if (durationSlider && durationVal) {
    durationSlider.addEventListener("input", (e) => {
      durationVal.textContent = `${e.target.value} Sols`;
    });
  }

  if (failureToggle && failureOptions) {
    failureToggle.addEventListener("change", (e) => {
      if (e.target.checked) failureOptions.classList.remove("hidden");
      else failureOptions.classList.add("hidden");
    });
  }

  function runSimulation() {
    const duration = parseInt(document.getElementById("simDurationSlider")?.value || 600);
    const hasFailure = document.getElementById("simFailureToggle")?.checked ?? true;
    const hasGanjaBLSS = document.getElementById("simGanjaToggle")?.checked ?? true;
    const failSol = parseInt(document.getElementById("simFailSolSlider")?.value || 150);
    const failDuration = parseInt(document.getElementById("simFailDurationSlider")?.value || 45);
    const peakTemp = parseFloat(document.getElementById("simPeakTempSlider")?.value || 31.5);

    const svg = document.getElementById("simulatorSvgChart");
    const verdictBanner = document.getElementById("simVerdictBanner");
    const advisoriesList = document.getElementById("simAdvisoriesList");

    const w = 720, h = 280, pad = 45;
    let foodSecurityPath = "";
    let thiaminePath = "";
    let ganjaBioBufferPath = "";
    const alerts = [];

    let thiaminePct = 100.0;
    let remainingMassPct = 100.0;
    let criticalSol = null;

    for (let sol = 0; sol <= duration; sol += 10) {
      const isExcursion = hasFailure && sol >= failSol && sol < (failSol + failDuration);
      const tempC = isExcursion ? peakTemp : 4.0;

      const k_b1 = calculateRateConstant(21000.0, 51.5, tempC);
      thiaminePct = firstOrderDecay(thiaminePct, k_b1, 10 * SOL_IN_EARTH_DAYS);
      remainingMassPct = Math.max(0, 100.0 - (sol / duration) * 85.0);

      // Ganja BLSS bio-buffer synthesis
      const ganjaBuffer = hasGanjaBLSS ? Math.min(100.0, 85.0 + Math.sin(sol / 40.0) * 8.0) : 0.0;

      // Composite food security index
      let secIndex = Math.round(0.35 * remainingMassPct + 0.35 * thiaminePct + 0.30 * 90.0);
      if (hasGanjaBLSS) {
        secIndex = Math.min(100, secIndex + 14); // Ganja fresh microgreen boost
      }

      if (isExcursion && sol === failSol) {
        alerts.push(`SOL-${sol} WARNING: Active Cooling Loop Failure (+${peakTemp}°C Thermal Spike)`);
      }

      if (!hasGanjaBLSS && thiaminePct < 50.0 && criticalSol === null) {
        criticalSol = sol;
        alerts.push(`SOL-${sol} CRITICAL: Prepackaged diet depleted of vital micronutrients! Severe crew beriberi & scurvy risk`);
      }

      if (hasGanjaBLSS && isExcursion && sol === failSol + 10) {
        alerts.push(`SOL-${sol} MITIGATION: Synthetic greenhouse microgreens (BIO-002) halted the nutrient crash (illustrative scenario)!`);
      }

      const x = pad + (sol / duration) * (w - pad * 2);
      const ySec = h - pad - (secIndex / 100.0) * (h - pad * 2);
      const yB1 = h - pad - (thiaminePct / 100.0) * (h - pad * 2);
      const yGanja = h - pad - (ganjaBuffer / 100.0) * (h - pad * 2);

      foodSecurityPath += sol === 0 ? `M ${x} ${ySec}` : ` L ${x} ${ySec}`;
      thiaminePath += sol === 0 ? `M ${x} ${yB1}` : ` L ${x} ${yB1}`;
      ganjaBioBufferPath += sol === 0 ? `M ${x} ${yGanja}` : ` L ${x} ${yGanja}`;
    }

    const sol450X = pad + (450 / duration) * (w - pad * 2);
    let excursionRect = "";
    if (hasFailure) {
      const exStartX = pad + (failSol / duration) * (w - pad * 2);
      const exEndX = pad + (Math.min(duration, failSol + failDuration) / duration) * (w - pad * 2);
      excursionRect = `
        <rect x="${exStartX}" y="${pad}" width="${Math.max(2, exEndX - exStartX)}" height="${h - pad * 2}" fill="#ef4444" fill-opacity="0.15"/>
        <text x="${exStartX + 4}" y="${pad + 16}" fill="#ef4444" font-size="10" font-family="monospace" font-weight="bold">COOLING MALFUNCTION (+${peakTemp}°C)</text>
      `;
    }

    if (svg) {
      svg.innerHTML = `
        <line x1="${pad}" y1="${h - pad}" x2="${w - pad}" y2="${h - pad}" stroke="#1f2e4d"/>
        <line x1="${pad}" y1="${pad}" x2="${pad}" y2="${h - pad}" stroke="#1f2e4d"/>
        
        <!-- Sol 450 Line -->
        <line x1="${sol450X}" y1="${pad}" x2="${sol450X}" y2="${h - pad}" stroke="#f97316" stroke-width="2" stroke-dasharray="4 4"/>
        <text x="${sol450X}" y="${pad - 6}" text-anchor="middle" fill="#f97316" font-size="10" font-weight="bold" font-family="monospace">SOL-450 TARGET</text>
        
        ${excursionRect}
        <path d="${thiaminePath}" fill="none" stroke="#06b6d4" stroke-width="2"/>
        ${hasGanjaBLSS ? `<path d="${ganjaBioBufferPath}" fill="none" stroke="#10b981" stroke-width="2.5" stroke-dasharray="3 3"/>` : ''}
        <path d="${foodSecurityPath}" fill="none" stroke="#f97316" stroke-width="3" stroke-linecap="round"/>
      `;
    }

    const survived = hasGanjaBLSS || criticalSol === null || criticalSol >= 450;
    if (verdictBanner) {
      verdictBanner.innerHTML = `
        <div class="flex items-center space-x-3 p-4 rounded-xl border ${survived ? 'bg-emerald-500/10 border-emerald-500/30 text-emerald-400' : 'bg-red-500/10 border-red-500/30 text-red-400'}">
          <i class="fa-solid ${survived ? 'fa-circle-check text-2xl' : 'fa-triangle-exclamation text-2xl'}"></i>
          <div>
            <span class="font-mono font-bold text-base block">
              ${survived ? 'MISSION VIABLE: SOL-450 OBJECTIVE ATTAINED' : `CRITICAL DEFICIT: DROP-DEAD AT SOL ${criticalSol}`}
            </span>
            <span class="text-xs text-slate-300 font-mono block mt-0.5">
              ${hasGanjaBLSS ? 'Synthetic greenhouse microgreens replenished Ascorbic Acid & antioxidants, insulating the crew.' : 'Prepackaged rations alone suffered lethal vitamin depletion during cooling failure.'}
            </span>
          </div>
        </div>
      `;
    }

    if (advisoriesList) {
      advisoriesList.innerHTML = alerts.map(a => `
        <div class="p-2.5 rounded bg-slate-900 border border-slate-800 text-slate-300 flex items-center justify-between text-xs font-mono">
          <span class="${a.includes('CRITICAL') ? 'text-red-400 font-bold' : a.includes('MITIGATION') ? 'text-emerald-400 font-bold' : 'text-amber-400 font-bold'}">${a}</span>
          <span class="text-[10px] text-slate-500">HAZARD LOG</span>
        </div>
      `).join('');
    }
  }

  if (runBtn) runBtn.addEventListener("click", runSimulation);
  if (ganjaToggle) ganjaToggle.addEventListener("change", runSimulation);
  runSimulation();
}

// ==================== VIEW 0 (HERO): CREW HEALTH MONITOR ====================
function initCrewHealth() {
  const crew = [
    { id: "C1", name: "Cmdr. Elena Rostova", role: "Commander & Astrobiologist", hr: 68, sleep: 7.4 },
    { id: "C2", name: "Dr. Marcus Chen", role: "Medical Officer & Flight Surgeon", hr: 71, sleep: 6.8 },
    { id: "C3", name: "Sarah Jenkins", role: "Life Support & Systems Engineer", hr: 64, sleep: 7.9 },
    { id: "C4", name: "Alex Rivera", role: "Mission Specialist & Geochemist", hr: 74, sleep: 6.5 }
  ];

  let selectedCrewId = "C1";
  let currentSol = 192;
  let hasFailure = true;

  const grid = document.getElementById("chCrewGrid");
  const svg = document.getElementById("chPoolSvgChart");
  const presetBtns = document.querySelectorAll(".ch-preset-btn");
  const solBadge = document.getElementById("chSolBadge");
  const alertBadge = document.getElementById("chAlertBadge");
  const alertBox = document.getElementById("chAlertBox");
  const presetDesc = document.getElementById("chPresetDesc");
  const metricVitC = document.getElementById("chMetricVitC");
  const metricB1 = document.getElementById("chMetricB1");
  const metricZ = document.getElementById("chMetricZ");
  const selectedCrewName = document.getElementById("chSelectedCrewName");

  function getStatus(sol, fail) {
    if (!fail) return "NOMINAL";
    if (sol < 150) return "NOMINAL";
    if (sol < 175) return "WATCH";
    return "ACT";
  }

  function renderCrewCards() {
    if (!grid) return;
    const status = getStatus(currentSol, hasFailure);
    const statusClass = status === 'ACT' 
      ? 'border-orange-500/60 bg-orange-950/30' 
      : status === 'WATCH' 
      ? 'border-amber-500/50 bg-amber-950/20' 
      : 'border-white/10 bg-slate-900/60';

    const badgeClass = status === 'ACT'
      ? 'bg-orange-500 text-white font-bold ring-2 ring-orange-400'
      : status === 'WATCH'
      ? 'bg-amber-500/20 text-amber-300 border border-amber-500/40 font-bold'
      : 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/40 font-bold';

    grid.innerHTML = crew.map(c => {
      const isSelected = c.id === selectedCrewId;
      return `
        <div class="cursor-pointer rounded-2xl p-4 border transition-all ${statusClass} ${isSelected ? 'ring-2 ring-orange-500 shadow-lg shadow-orange-500/20' : 'hover:border-white/30'}" onclick="selectCrew('${c.id}')">
          <div class="flex items-center justify-between mb-3">
            <span class="text-[10px] font-mono px-2 py-0.5 rounded-full ${badgeClass}">
              ${status === 'ACT' ? '● ACT NOW' : status === 'WATCH' ? '● WATCH' : '● NOMINAL'}
            </span>
            <span class="text-[10px] font-mono text-slate-400">ID: ${c.id}</span>
          </div>
          <div class="flex items-center space-x-3">
            <div class="w-11 h-11 rounded-xl bg-slate-800 border border-white/10 overflow-hidden shrink-0 flex items-center justify-center">
              <i class="fa-solid fa-user-astronaut text-xl text-orange-400"></i>
            </div>
            <div class="min-w-0">
              <h4 class="font-bold text-white text-sm truncate font-mono">${c.name}</h4>
              <p class="text-[10px] text-slate-400 truncate">${c.role}</p>
            </div>
          </div>
          <div class="grid grid-cols-2 gap-2 mt-3 pt-3 border-t border-white/10 text-[11px] font-mono">
            <div>
              <span class="text-[9px] text-slate-500 block uppercase">Resting HR</span>
              <span class="font-bold ${status === 'ACT' ? 'text-orange-400' : 'text-slate-200'}">${c.hr + (status === 'ACT' ? 9 : status === 'WATCH' ? 4 : 0)} bpm</span>
            </div>
            <div>
              <span class="text-[9px] text-slate-500 block uppercase">Sleep Avg</span>
              <span class="font-bold text-slate-200">${(c.sleep - (status === 'ACT' ? 1.2 : 0)).toFixed(1)} h/sol</span>
            </div>
          </div>
        </div>
      `;
    }).join('');
  }

  window.selectCrew = function(id) {
    selectedCrewId = id;
    const c = crew.find(x => x.id === id);
    if (selectedCrewName && c) selectedCrewName.textContent = c.name;
    renderCrewCards();
    renderChart();
  };

  function renderChart() {
    if (!svg) return;
    const w = 700;
    const h = 250;
    const padL = 50;
    const padR = 20;
    const padT = 20;
    const padB = 30;

    const sx = (sol) => padL + (sol / 300) * (w - padL - padR);
    const sy = (pct) => h - padB - (pct / 100) * (h - padT - padB);

    let vitCPts = [];
    let b1Pts = [];

    for (let sol = 0; sol <= 300; sol += 5) {
      let vitC = 100;
      let b1 = 100;
      if (hasFailure && sol >= 150) {
        const dt = sol - 150;
        vitC = Math.max(22, 100 - (dt / 120) * 65);
        b1 = Math.max(28, 100 - (dt / 120) * 58);
      } else {
        vitC = Math.max(88, 100 - (sol / 300) * 10);
        b1 = Math.max(85, 100 - (sol / 300) * 12);
      }
      vitCPts.push(`${sx(sol).toFixed(1)} ${sy(vitC).toFixed(1)}`);
      b1Pts.push(`${sx(sol).toFixed(1)} ${sy(b1).toFixed(1)}`);
    }

    const solX = sx(currentSol);
    const failX = sx(150);
    const riskY = sy(40);

    let failureBand = "";
    if (hasFailure) {
      failureBand = `
        <rect x="${failX}" y="${padT}" width="${sx(300) - failX}" height="${h - padT - padB}" fill="#ff6b18" fill-opacity="0.08"/>
        <line x1="${failX}" y1="${padT}" x2="${failX}" y2="${h - padB}" stroke="#ff6b18" stroke-width="1.5" stroke-dasharray="3 3"/>
        <text x="${failX + 6}" y="${padT + 14}" fill="#ff6b18" font-size="10" font-family="monospace" font-weight="bold">SOL 150: CHILLER LOOP FAULT (+28°C)</text>
      `;
    }

    svg.innerHTML = `
      <line x1="${padL}" y1="${h - padB}" x2="${w - padR}" y2="${h - padB}" stroke="rgba(255,255,255,0.15)"/>
      <line x1="${padL}" y1="${padT}" x2="${padL}" y2="${h - padB}" stroke="rgba(255,255,255,0.15)"/>

      <line x1="${padL}" y1="${riskY}" x2="${w - padR}" y2="${riskY}" stroke="#ef4444" stroke-width="1.5" stroke-dasharray="4 4"/>
      <text x="${w - padR}" y="${riskY - 6}" fill="#ef4444" font-size="9" font-family="monospace" font-weight="bold" text-anchor="end">40% CLINICAL DEFICIENCY THRESHOLD</text>

      ${failureBand}

      <path d="M ${vitCPts.join(' L ')}" fill="none" stroke="#22d3ee" stroke-width="2.5"/>
      <path d="M ${b1Pts.join(' L ')}" fill="none" stroke="#fbbf24" stroke-width="2.5"/>

      <line x1="${solX}" y1="${padT}" x2="${solX}" y2="${h - padB}" stroke="#ff6b18" stroke-width="2.5"/>
      <circle cx="${solX}" cy="${padT + 8}" r="4" fill="#ff6b18"/>
      <text x="${solX}" y="${h - padB + 18}" fill="#ff6b18" font-size="10" font-family="monospace" font-weight="bold" text-anchor="middle">SOL ${currentSol}</text>
    `;

    let cPool = 96, b1Pool = 94, zScore = 0.3;
    if (hasFailure && currentSol >= 150) {
      const dt = currentSol - 150;
      cPool = Math.round(Math.max(22, 100 - (dt / 120) * 65));
      b1Pool = Math.round(Math.max(28, 100 - (dt / 120) * 58));
      zScore = (0.3 + (dt / 42) * 2.1).toFixed(1);
    }
    if (metricVitC) metricVitC.textContent = `${cPool}%`;
    if (metricB1) metricB1.textContent = `${b1Pool}%`;
    if (metricZ) metricZ.textContent = `+${zScore}σ vs Baseline`;
  }

  function applyPreset(sol, fail, desc) {
    currentSol = sol;
    hasFailure = fail;

    if (solBadge) solBadge.textContent = `SOL ${sol}`;
    if (presetDesc) presetDesc.textContent = desc;

    const status = getStatus(sol, fail);
    if (alertBadge) {
      alertBadge.textContent = status === 'ACT' ? 'ACT NOW' : status === 'WATCH' ? 'WATCH' : 'NOMINAL';
      alertBadge.className = `px-2.5 py-0.5 rounded-full text-[10px] font-mono font-bold ${
        status === 'ACT' ? 'bg-orange-500 text-white animate-pulse' : status === 'WATCH' ? 'bg-amber-500 text-black' : 'bg-emerald-500 text-white'
      }`;
    }

    if (alertBox) {
      if (status === 'ACT') {
        alertBox.innerHTML = `
          <div class="p-3.5 rounded-xl bg-black/40 border border-orange-500/40 space-y-1.5">
            <span class="text-orange-400 font-bold block">WHAT CHANGED &amp; SINCE WHEN</span>
            <p class="text-slate-200 leading-relaxed">
              Chiller loop fault at <strong class="text-white">Sol 150</strong> (+28°C). Arrhenius kinetics degraded daily Thiamine intake by 38% and Vitamin C by 44% over 42 Sols.
            </p>
          </div>
          <div class="p-3.5 rounded-xl bg-emerald-500/10 border border-emerald-500/30 space-y-1.5">
            <span class="text-emerald-300 font-bold block">PRESCRIPTIVE COUNTERMEASURE (WHAT TO EAT)</span>
            <p class="text-slate-200 leading-relaxed">
              Add <strong class="text-white">+50g/day Radish Microgreens (BIO-002)</strong> (+74 mg Vit-C) + <strong class="text-white">+100g Lentil Vegetable Stew (TH-002)</strong> (+0.48 mg B1) to restore pool &gt;85% within 14 Sols.
            </p>
          </div>
        `;
      } else if (status === 'WATCH') {
        alertBox.innerHTML = `
          <div class="p-3.5 rounded-xl bg-black/40 border border-amber-500/40 space-y-1.5">
            <span class="text-amber-400 font-bold block">EARLY DRIFT DETECTED</span>
            <p class="text-slate-200 leading-relaxed">
              Sol 165 (+15 Sols post-failure): Personal baseline resting HR has drifted to +1.4σ. Storage temperature remains elevated at +28°C.
            </p>
          </div>
          <div class="p-3.5 rounded-xl bg-slate-900 border border-white/10 space-y-1.5">
            <span class="text-slate-300 font-bold block">PRECAUTIONARY GUIDANCE</span>
            <p class="text-slate-400 leading-relaxed">
              Begin pre-allocating bio-regenerative microgreen trays to avoid crossing the 40% clinical deficit cutoff at ~Sol 240.
            </p>
          </div>
        `;
      } else {
        alertBox.innerHTML = `
          <div class="p-3.5 rounded-xl bg-emerald-500/10 border border-emerald-500/30 space-y-1.5">
            <span class="text-emerald-400 font-bold block">SYSTEM NOMINAL — NO DEFICIT DETECTED</span>
            <p class="text-slate-200 leading-relaxed">
              All 4 crew members exhibit body vitamin pools &gt;90% of saturation capacity. Storage temperatures stable at +4.0°C.
            </p>
          </div>
          <div class="p-3.5 rounded-xl bg-slate-900 border border-white/10 space-y-1.5">
            <span class="text-slate-300 font-bold block">BASELINE STABILITY</span>
            <p class="text-slate-400 leading-relaxed">
              Vital telemetry remains within personal L-90..Sol 30 baseline bands. Zero false positive advisories generated.
            </p>
          </div>
        `;
      }
    }

    renderCrewCards();
    renderChart();
  }

  presetBtns.forEach(btn => {
    btn.addEventListener("click", () => {
      presetBtns.forEach(b => {
        b.classList.remove("bg-orange-500", "text-white", "shadow-lg", "shadow-orange-500/30");
        b.classList.add("bg-slate-900/90", "text-slate-200");
      });
      btn.classList.add("bg-orange-500", "text-white", "shadow-lg", "shadow-orange-500/30");
      btn.classList.remove("bg-slate-900/90", "text-slate-200");

      const sol = parseInt(btn.getAttribute("data-sol"));
      const fail = btn.getAttribute("data-fail") === "1";
      const desc = sol === 149 
        ? "Pre-failure baseline: storage at 4°C, all body pools nominal (>95%), zero alerts."
        : sol === 165
        ? "15 Sols after cooling malfunction: early drift identified by personal-baseline z-score detector (WATCH state)."
        : fail
        ? "Cooling failure at Sol 150 (+28°C) accelerates food Vitamin C & B1 loss → ACT alert triggers at Sol 192 (before crossing risk threshold)."
        : "Control scenario with 0 failures: food remains at 4°C, zero false alarms triggered throughout entire mission.";

      applyPreset(sol, fail, desc);
    });
  });

  applyPreset(192, true, "Cooling failure at Sol 150 (+28°C) accelerates food Vitamin C & B1 loss → ACT alert triggers at Sol 192 (before crossing risk threshold).");
}

// ===========================================================================
// VIEW 9: ECLSS & SMART REGOLITH HYDRO-MANAGEMENT SIMULATION ENGINE (FARUK)
// ===========================================================================
function initLifeSupportSim() {
  const kpiGrid = document.getElementById("lsKpiGrid");
  if (!kpiGrid) return;

  let sol = 450;
  let crewSize = 4;
  let dustStorm = false;
  let o2Leak = false;
  let closedLoop = true;

  const solSlider = document.getElementById("lsSolSlider");
  const solVal = document.getElementById("lsSolVal");
  const crewSlider = document.getElementById("lsCrewSlider");
  const crewVal = document.getElementById("lsCrewVal");
  const dustToggle = document.getElementById("lsDustToggle");
  const dustBadge = document.getElementById("lsDustBadge");
  const leakToggle = document.getElementById("lsLeakToggle");
  const leakBadge = document.getElementById("lsLeakBadge");
  const loopToggle = document.getElementById("lsLoopToggle");
  const loopBadge = document.getElementById("lsLoopBadge");

  function renderECLSS() {
    if (solVal) solVal.textContent = `Sol ${sol}`;
    if (crewVal) crewVal.textContent = `${crewSize} Astronauts`;

    const o2Demand = crewSize * 0.816;
    const co2Produced = crewSize * 1.04;
    const waterDemand = crewSize * (2.50 + 7.32);

    const ogsO2 = closedLoop ? o2Demand * 0.63 + 1.24 : 0.0;
    const sabatierWater = closedLoop ? co2Produced * 0.818 : 0.0;
    const wrsClosurePct = closedLoop ? 94.0 : 0.0;
    const netWaterrecovered = closedLoop ? waterDemand * 0.94 + sabatierWater : 0.0;

    const pO2 = o2Leak ? 19.4 : 21.3;
    const pCO2 = closedLoop ? 0.38 : 0.74;
    const solarGen = dustStorm ? 42.0 : 148.0;
    const powerDraw = 32.0 + crewSize * 8.5 + (closedLoop ? 24.0 : 6.0);
    const netPower = solarGen - powerDraw;

    // Status
    let overall = "OPTIMAL";
    if (!closedLoop || (dustStorm && o2Leak)) overall = "CRITICAL";
    else if (dustStorm || o2Leak) overall = "WARNING";

    const stateEl = document.getElementById("lsOverallState");
    const dotEl = document.getElementById("lsStatusDot");
    const closureEl = document.getElementById("lsWaterClosureLabel");
    if (stateEl) stateEl.textContent = overall;
    if (dotEl) {
      dotEl.className = `w-2.5 h-2.5 rounded-full animate-pulse ${overall === 'CRITICAL' ? 'bg-red-500' : overall === 'WARNING' ? 'bg-amber-400' : 'bg-emerald-400'}`;
    }
    if (closureEl) closureEl.textContent = `${wrsClosurePct.toFixed(1)}%`;

    kpiGrid.innerHTML = `
      <div class="glass-panel rounded-xl p-4 border border-slate-800 font-mono">
        <span class="text-[10px] text-slate-400 uppercase block">Atmosphere &amp; OGS Electrolysis</span>
        <div class="text-xl font-bold text-emerald-400 mt-1">pO₂ ${pO2.toFixed(1)} kPa</div>
        <div class="text-[11px] text-slate-300 mt-1">OGS Output: +${ogsO2.toFixed(2)} kg O₂/Sol</div>
        <div class="text-[10px] text-slate-500 mt-0.5">Crew Demand: ${o2Demand.toFixed(2)} kg/Sol · pCO₂ ${pCO2.toFixed(2)} kPa</div>
      </div>
      <div class="glass-panel rounded-xl p-4 border border-slate-800 font-mono">
        <span class="text-[10px] text-slate-400 uppercase block">Sabatier &amp; WRS Water Loop</span>
        <div class="text-xl font-bold text-cyan-400 mt-1">${wrsClosurePct.toFixed(1)}% Closure</div>
        <div class="text-[11px] text-slate-300 mt-1">Recovered: ${netWaterrecovered.toFixed(1)} L/Sol</div>
        <div class="text-[10px] text-slate-500 mt-0.5">Sabatier Yield: +${sabatierWater.toFixed(2)} L H₂O/Sol</div>
      </div>
      <div class="glass-panel rounded-xl p-4 border border-slate-800 font-mono">
        <span class="text-[10px] text-slate-400 uppercase block">Habitat Microgrid &amp; Solar Array</span>
        <div class="text-xl font-bold ${netPower >= 0 ? 'text-amber-400' : 'text-red-400'} mt-1">${solarGen.toFixed(1)} kWh/Sol</div>
        <div class="text-[11px] text-slate-300 mt-1">Load: ${powerDraw.toFixed(1)} kWh/Sol (${netPower >= 0 ? '+' : ''}${netPower.toFixed(1)})</div>
        <div class="text-[10px] text-slate-500 mt-0.5">${dustStorm ? 'Dust Storm Attenuation (-72%)' : 'Nominal Martian Irradiance'}</div>
      </div>
      <div class="glass-panel rounded-xl p-4 border border-slate-800 font-mono">
        <span class="text-[10px] text-slate-400 uppercase block">Cabin Pressure &amp; Seal Integrity</span>
        <div class="text-xl font-bold ${o2Leak ? 'text-red-400' : 'text-purple-400'} mt-1">${o2Leak ? '98.4 kPa' : '101.3 kPa'}</div>
        <div class="text-[11px] text-slate-300 mt-1">${o2Leak ? 'Leak Active (-1.45 kg O₂/Sol)' : 'Zero Seal Leakage'}</div>
        <div class="text-[10px] text-slate-500 mt-0.5">N₂/O₂ Buffer Auto-Injection Ready</div>
      </div>
    `;

    // 3 synthetic crop beds (software-simulated soil moisture, no hardware)
    const baseNodes = [
      { id: "BED-01", zone: "Bed 1 • Microgreens (synthetic)", crop: "Microgreens", depth: "8 cm", vwcBase: 46.2, ec: 1.65, ph: 6.4 },
      { id: "BED-02", zone: "Bed 2 • Dwarf Cherry Tomato (synthetic)", crop: "Dwarf Cherry Tomato", depth: "18 cm", vwcBase: 36.8, ec: 2.15, ph: 6.6 },
      { id: "BED-03", zone: "Bed 3 • Dwarf Sweet Potato (synthetic)", crop: "Dwarf Sweet Potato", depth: "22 cm", vwcBase: 42.5, ec: 3.10, ph: 6.7 }
    ];

    const sensorsGrid = document.getElementById("lsSensorsGrid");
    if (sensorsGrid) {
      sensorsGrid.innerHTML = baseNodes.map((n, i) => {
        const wave = Math.sin((sol + i * 23) * 0.25) * 4.2;
        const vwc = Math.max(24.0, Math.min(56.0, n.vwcBase + wave - (closedLoop ? 0 : 11.0)));
        const valveOpen = vwc <= 38.0;
        return `
          <div class="p-3.5 rounded-xl bg-slate-900/80 border ${valveOpen ? 'border-cyan-500/50' : 'border-slate-800'} space-y-2 text-xs">
            <div class="flex items-center justify-between">
              <span class="font-bold text-white">${n.id}</span>
              <span class="px-2 py-0.5 rounded text-[10px] font-bold ${valveOpen ? 'bg-cyan-500/20 text-cyan-300 border border-cyan-500/40' : 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/30'}">
                ${valveOpen ? 'VALVE OPEN (IRRIGATING)' : 'STANDBY (NOMINAL)'}
              </span>
            </div>
            <div class="text-[11px] text-slate-300 font-semibold">${n.zone}</div>
            <div class="text-[10px] text-slate-400">Crop: ${n.crop} · Probe Depth: ${n.depth}</div>
            <div>
              <div class="flex justify-between text-[10px] mb-0.5">
                <span class="text-slate-400">Volumetric Water (VWC)</span>
                <span class="font-bold text-cyan-300">${vwc.toFixed(1)}%</span>
              </div>
              <div class="h-1.5 bg-slate-950 rounded overflow-hidden">
                <div class="h-full bg-cyan-400 rounded" style="width:${vwc}%"></div>
              </div>
            </div>
            <div class="flex justify-between text-[10px] text-slate-400 pt-1 border-t border-slate-800/80">
              <span>Salinity EC: ${n.ec.toFixed(2)} dS/m</span>
              <span>pH: ${n.ph}</span>
            </div>
          </div>
        `;
      }).join("");
    }

    // 450-Sol trajectory SVG
    const W = 820, H = 220, padL = 48, padR = 20, padT = 20, padB = 28;
    const sx = (s) => padL + (s / 450) * (W - padL - padR);
    const sy = (pct) => H - padB - (Math.max(0, Math.min(100, pct)) / 100) * (H - padT - padB);

    let o2Pts = [], h2oPts = [], socPts = [];
    let o2Pct = 100, h2oPct = 100, socPct = 96;
    for (let s = 0; s <= 450; s += 10) {
      const inStorm = dustStorm && s >= 180 && s <= 240;
      const inLeak = o2Leak && s >= 280 && s <= 310;
      o2Pct = Math.max(5, o2Pct - (closedLoop ? 0.08 : 0.85) - (inLeak ? 1.8 : 0));
      h2oPct = Math.max(5, h2oPct - (closedLoop ? 0.06 : 0.92));
      socPct = inStorm ? Math.max(28, socPct - 3.2) : Math.min(98, socPct + 2.5);
      o2Pts.push(`${s === 0 ? 'M' : 'L'} ${sx(s).toFixed(1)} ${sy(o2Pct).toFixed(1)}`);
      h2oPts.push(`${s === 0 ? 'M' : 'L'} ${sx(s).toFixed(1)} ${sy(h2oPct).toFixed(1)}`);
      socPts.push(`${s === 0 ? 'M' : 'L'} ${sx(s).toFixed(1)} ${sy(socPct).toFixed(1)}`);
    }

    const chartBox = document.getElementById("lsTrajectoryChartBox");
    if (chartBox) {
      chartBox.innerHTML = `
        <div class="bg-slate-950 rounded-lg p-3 border border-slate-800">
          <div class="flex flex-wrap items-center justify-between gap-2 mb-2 font-mono text-[11px]">
            <div class="flex items-center space-x-4">
              <span class="flex items-center space-x-1.5"><span class="w-3 h-0.5 bg-emerald-400 inline-block"></span><span class="text-slate-300">O₂ Reserve (%)</span></span>
              <span class="flex items-center space-x-1.5"><span class="w-3 h-0.5 bg-cyan-400 inline-block"></span><span class="text-slate-300">Potable H₂O Reserve (%)</span></span>
              <span class="flex items-center space-x-1.5"><span class="w-3 h-0.5 bg-amber-400 inline-block"></span><span class="text-slate-300">Battery SOC (%)</span></span>
            </div>
            <span class="text-slate-400">Sol 0 &rarr; Sol 450</span>
          </div>
          <svg viewBox="0 0 ${W} ${H}" class="w-full h-auto">
            <line x1="${padL}" y1="${sy(25)}" x2="${W - padR}" y2="${sy(25)}" stroke="#1f2e4d" stroke-dasharray="3 3"/>
            <line x1="${padL}" y1="${sy(50)}" x2="${W - padR}" y2="${sy(50)}" stroke="#1f2e4d" stroke-dasharray="3 3"/>
            <line x1="${padL}" y1="${sy(75)}" x2="${W - padR}" y2="${sy(75)}" stroke="#1f2e4d" stroke-dasharray="3 3"/>
            ${dustStorm ? `<rect x="${sx(180)}" y="${padT}" width="${sx(240) - sx(180)}" height="${H - padT - padB}" fill="#f59e0b" opacity="0.14"/>` : ""}
            ${o2Leak ? `<rect x="${sx(280)}" y="${padT}" width="${sx(310) - sx(280)}" height="${H - padT - padB}" fill="#ef4444" opacity="0.15"/>` : ""}
            <path d="${o2Pts.join(" ")}" fill="none" stroke="#10b981" stroke-width="2.4"/>
            <path d="${h2oPts.join(" ")}" fill="none" stroke="#06b6d4" stroke-width="2.4"/>
            <path d="${socPts.join(" ")}" fill="none" stroke="#f59e0b" stroke-width="1.8" stroke-dasharray="4 3"/>
            <line x1="${sx(sol)}" y1="${padT}" x2="${sx(sol)}" y2="${H - padB}" stroke="#e2e8f0" stroke-width="1.2"/>
          </svg>
        </div>
      `;
    }

    const verdictEl = document.getElementById("lsVerdictBadge");
    const survived = o2Pct > 20 && h2oPct > 20;
    if (verdictEl) {
      verdictEl.textContent = survived ? "VERDICT: NOMINAL_SURVIVED (SOL 450)" : "VERDICT: CONSUMABLE DEPLETION";
      verdictEl.className = survived
        ? "px-3 py-1 rounded border text-xs font-mono font-bold bg-emerald-500/10 border-emerald-500/40 text-emerald-300"
        : "px-3 py-1 rounded border text-xs font-mono font-bold bg-red-500/10 border-red-500/40 text-red-400";
    }
  }

  if (solSlider) solSlider.addEventListener("input", e => { sol = parseInt(e.target.value, 10); renderECLSS(); });
  if (crewSlider) crewSlider.addEventListener("input", e => { crewSize = parseInt(e.target.value, 10); renderECLSS(); });
  if (dustToggle) {
    dustToggle.addEventListener("click", () => {
      dustStorm = !dustStorm;
      if (dustBadge) {
        dustBadge.textContent = dustStorm ? "ACTIVE" : "INACTIVE";
        dustBadge.className = dustStorm ? "text-[10px] px-1.5 py-0.5 rounded bg-amber-500/20 text-amber-300 font-bold" : "text-[10px] px-1.5 py-0.5 rounded bg-slate-800 text-slate-400";
      }
      renderECLSS();
    });
  }
  if (leakToggle) {
    leakToggle.addEventListener("click", () => {
      o2Leak = !o2Leak;
      if (leakBadge) {
        leakBadge.textContent = o2Leak ? "LEAK ACTIVE" : "NOMINAL";
        leakBadge.className = o2Leak ? "text-[10px] px-1.5 py-0.5 rounded bg-red-500/20 text-red-300 font-bold" : "text-[10px] px-1.5 py-0.5 rounded bg-slate-800 text-slate-400";
      }
      renderECLSS();
    });
  }
  if (loopToggle) {
    loopToggle.addEventListener("click", () => {
      closedLoop = !closedLoop;
      if (loopBadge) {
        loopBadge.textContent = closedLoop ? "ENABLED" : "OPEN-LOOP";
        loopBadge.className = closedLoop ? "text-[10px] px-1.5 py-0.5 rounded bg-emerald-500/20 text-emerald-300 font-bold" : "text-[10px] px-1.5 py-0.5 rounded bg-red-500/20 text-red-300 font-bold";
      }
      renderECLSS();
    });
  }

  renderECLSS();
}
